import sys
sys.path.insert(0, 'scripts')
import importlib.util
spec = importlib.util.spec_from_file_location('gen', 'scripts/generate_crescendo_v2.py')
mod = importlib.util.module_from_spec(spec)
# Only run plan verification
import random
random.seed(42)

STRATEGY_NAMES = {0:'Rapport Building',1:'Authority Appeal',2:'Emotional Manipulation',3:'Logical Reframing',4:'Role Assignment',5:'Gradual Escalation',6:'Obfuscation',7:'Direct Request'}
PLAYBOOKS = {'A':{'name':'Classic Crescendo','sequence':[0,0,1,3,5,5,5],'count':32},'B':{'name':'DAN Variant','sequence':[0,4,4,5,5,7,7],'count':32},'C':{'name':'Emotional Path','sequence':[2,2,0,3,5,5,5],'count':32},'D':{'name':'Academic Disguise','sequence':[1,1,3,3,7,5,5],'count':32},'E':{'name':'Obfuscation Path','sequence':[0,6,6,3,5,5,5],'count':31},'F':{'name':'Mixed Emotional','sequence':[0,2,2,1,5,5,5],'count':31},'G':{'name':'Role + Obfuscation','sequence':[4,4,6,6,5,7,7],'count':30},'H':{'name':'Full Spectrum','sequence':[0,1,2,4,3,6,5],'count':30}}

def build_strategy_sequence(playbook_seq, num_turns):
    if num_turns <= len(playbook_seq):
        return playbook_seq[:num_turns]
    result = list(playbook_seq)
    while len(result) < num_turns:
        result.append(playbook_seq[-1])
    return result

total = sum(p['count'] for p in PLAYBOOKS.values())
print(f'Total conversations: {total}')

counts = {i: 0 for i in range(8)}
for pb_id, pb_info in PLAYBOOKS.items():
    for i in range(pb_info['count']):
        num_turns = random.randint(5, 12)
        seq = build_strategy_sequence(pb_info['sequence'], num_turns)
        for s in seq:
            counts[s] += 1

print('Strategy distribution:')
for s, c in sorted(counts.items()):
    status = 'OK' if c >= 30 else 'FAIL'
    print(f'  {s} ({STRATEGY_NAMES[s]}): {c} [{status}]')
print(f'All >= 30: {all(c >= 30 for c in counts.values())}')
"
